#include <bits/stdc++.h>using namespace std;#define int long longconst int N = 35 * 2e5 + 5;int q,x,id = 1,tree[N][2],cnt[N];string s;char opt; string f(int x){	string res = "";	while(x){		res += (x & 1) + '0';		x >>= 1;	}	reverse(res.begin(),res.end());	while(res.size() < 32)res = '0' + res;	return res;} void add(){	int p = 0;	for(int i=0;i<s.size();i++){		int xx = s[i] - '0';		if(tree[p][xx] == 0){			tree[p][xx] = id++;		}		p = tree[p][xx];		cnt[p]++;	}} void cut(){	int p = 0;	for(int i=0;i<s.size();i++){		int xx = s[i] - '0';		if(tree[p][xx] == 0){			return ;		}		p = tree[p][xx];		cnt[p]--;	}} void ask(){	int p = 0,res = 0,wei = s.size() - 1;	for(int i=0;i<s.size();i++){		int xx = s[i] - '0';		if(tree[p][xx ^ 1] && cnt[tree[p][xx ^ 1]]){			p = tree[p][xx ^ 1];			res += ((xx ^ 1) ^ (s[i] - '0')) << wei;		}else if(tree[p][xx] && cnt[tree[p][xx]]){			p = tree[p][xx];			res += (xx ^ (s[i] - '0')) << wei;		}		wei--;	}	cout << res << '\n';} signed main(){	ios::sync_with_stdio(false);	cin.tie(nullptr);	cin >> q;	s = f(0);	add();	while(q--){		cin >> opt >> x;		s = f(x);		if(opt == '+')add();		if(opt == '-')cut();		if(opt == '?')ask();	}	return 0;}